  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 public access block is missing",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The CloudTrail log bucket has no account-level bucket public access controls, increasing the risk that a future ACL or bucket policy could expose audit logs publicly."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is disabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "Without versioning, CloudTrail log objects cannot be recovered after accidental overwrite or deletion."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket does not use KMS encryption by default",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The bucket does not explicitly enforce KMS-backed default encryption for its security-sensitive CloudTrail logs."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "S3 lifecycle configuration is missing",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The bucket has no lifecycle configuration to clean up incomplete multipart uploads, which can leave unnecessary storage artifacts indefinitely."
    },
    {
      "check_id": "CKV_AWS_70",
      "title": "S3 bucket does not enforce encrypted transport",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "No bucket policy denies requests made without TLS, so CloudTrail log objects could be accessed over an unencrypted transport path."
    },
    {
      "check_id": "UNKNOWN",
      "title": "CloudTrail log bucket permits destructive deletion",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "The bucket sets force_destroy to true, allowing Terraform to delete the bucket and all retained audit logs during resource destruction."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = "smart-city-parking-management-system-s3-cloudtrail-${random_string.cloudtrail_suffix.result}"
  force_destroy = false
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

